38	const GLM52_WEIGHT_INDEX: &str = "model.safetensors.index.json";
39	/// The EP8 production partition (8 ranks × 32 experts). Serving-path code
40	/// derives rank/expert counts from the launch topology
41	/// (`Glm52MoeTopo::ep_local_experts`); these constants remain the manifest
42	/// coverage partition (`rank_tensor_names` / `validate_rank_coverage`, which
43	/// only needs SOME partition covering every checkpoint tensor) and the EP8
44	/// chain's shim contract check.
45	pub(crate) const GLM52_EP_RANKS: usize = 8;
46	const GLM52_LOCAL_EXPERTS: usize = GLM52_ROUTED_EXPERTS / GLM52_EP_RANKS;
47	const FP8_BLOCK_SIZE: usize = 128;
48	
49	// ---------------------------------------------------------------------------
50	// Expert packed placement: routed-expert tensors are written into their FINAL
51	// expert-major layout at H2D time (per expert: [gate; up] rows, scales
52	// likewise), byte-identical to `Glm52MoeExpertBank::pack_from_host` packing.
53	// Repacking after load cannot work — a rank's expert slab (~85 GiB) plus its
54	// packed copy exceeds the 141 GiB HBM — so placement happens in the loader.
55	// ---------------------------------------------------------------------------
56	
57	/// Per-expert byte strides of the packed regions (expert intermediate 2048,
58	/// hidden 6144, fp8 weights + f32 128×128-block scales).
59	const EXPERT_PROJ_W13_BYTES: usize = GLM52_EXPERT_INTERMEDIATE * GLM52_HIDDEN; // one of gate|up
60	const EXPERT_W13_WEIGHT_STRIDE: usize = 2 * EXPERT_PROJ_W13_BYTES;
61	const EXPERT_PROJ_W13_SCALE_BYTES: usize =
62	    GLM52_EXPERT_INTERMEDIATE.div_ceil(FP8_BLOCK_SIZE) * GLM52_HIDDEN.div_ceil(FP8_BLOCK_SIZE) * 4;
63	const EXPERT_W13_SCALE_STRIDE: usize = 2 * EXPERT_PROJ_W13_SCALE_BYTES;
64	const EXPERT_W2_WEIGHT_STRIDE: usize = GLM52_HIDDEN * GLM52_EXPERT_INTERMEDIATE;
65	const EXPERT_W2_SCALE_STRIDE: usize =
66	    GLM52_HIDDEN.div_ceil(FP8_BLOCK_SIZE) * GLM52_EXPERT_INTERMEDIATE.div_ceil(FP8_BLOCK_SIZE) * 4;
67	
68	#[derive(Clone, Copy, Debug, Eq, PartialEq, PartialOrd, Ord)]
69	pub(crate) enum Glm52ExpertRegionKind {
70	    W13Weight,
71	    W13Scale,
72	    W2Weight,
73	    W2Scale,
74	}
75	
76	impl Glm52ExpertRegionKind {
77	    const ALL: [Self; 4] = [
78	        Self::W13Weight,
79	        Self::W13Scale,
80	        Self::W2Weight,
81	        Self::W2Scale,
82	    ];
83	
84	    /// Total bytes of this region for one layer's rank-local experts
85	    /// (`local_experts` = 32 for EP8, 64 for EP4).
86	    fn region_bytes(self, local_experts: usize) -> usize {
87	        local_experts * self.expert_stride()
88	    }
89	
90	    pub(crate) fn expert_stride(self) -> usize {
91	        match self {
92	            Self::W13Weight => EXPERT_W13_WEIGHT_STRIDE,
93	            Self::W13Scale => EXPERT_W13_SCALE_STRIDE,
94	            Self::W2Weight => EXPERT_W2_WEIGHT_STRIDE,
95	            Self::W2Scale => EXPERT_W2_SCALE_STRIDE,
96	        }
97	    }
98	}
