100	/// Destination of one routed-expert tensor inside its layer's packed regions.
101	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
102	pub(crate) struct Glm52ExpertPlacement {
103	    layer: usize,
104	    region: Glm52ExpertRegionKind,
105	    offset: usize,
106	}
107	
108	/// Classify a tensor name: `Some(placement)` for routed-expert tensors (the
109	/// expert index must fall in this rank's range), `None` for everything else
110	/// (own-region tensors). Fails loudly on a malformed expert name or an expert
111	/// outside the rank's range — either means the load plan is corrupt.
112	pub(crate) fn expert_placement(
113	    name: &str,
114	    rank_experts: &std::ops::Range<usize>,
115	) -> Result<Option<Glm52ExpertPlacement>> {
116	    use Glm52ExpertRegionKind::W2Scale;
117	    use Glm52ExpertRegionKind::W2Weight;
118	    use Glm52ExpertRegionKind::W13Scale;
119	    use Glm52ExpertRegionKind::W13Weight;
120	
121	    let Some((layer, rest)) = name
122	        .strip_prefix("model.layers.")
123	        .and_then(|rest| rest.split_once(".mlp.experts."))
124	    else {
125	        return Ok(None);
126	    };
127	    let layer = layer
128	        .parse::<usize>()
129	        .with_context(|| format!("GLM5.2 expert tensor has invalid layer index: {name}"))?;
130	    let (expert, proj) = rest
131	        .split_once('.')
132	        .ok_or_else(|| anyhow::anyhow!("GLM5.2 expert tensor has malformed name: {name}"))?;
133	    let expert = expert
134	        .parse::<usize>()
135	        .with_context(|| format!("GLM5.2 expert tensor has invalid expert index: {name}"))?;
136	    ensure!(
137	        rank_experts.contains(&expert),
138	        "GLM5.2 expert tensor {name} is outside this rank's expert range {rank_experts:?}"
139	    );
140	    let local = expert - rank_experts.start;
141	
142	    let (region, offset) = match proj {
143	        "gate_proj.weight" => (W13Weight, local * EXPERT_W13_WEIGHT_STRIDE),
144	        "up_proj.weight" => (
145	            W13Weight,
146	            local * EXPERT_W13_WEIGHT_STRIDE + EXPERT_PROJ_W13_BYTES,
147	        ),
148	        "gate_proj.weight_scale_inv" => (W13Scale, local * EXPERT_W13_SCALE_STRIDE),
149	        "up_proj.weight_scale_inv" => (
150	            W13Scale,
151	            local * EXPERT_W13_SCALE_STRIDE + EXPERT_PROJ_W13_SCALE_BYTES,
152	        ),
153	        "down_proj.weight" => (W2Weight, local * EXPERT_W2_WEIGHT_STRIDE),
154	        "down_proj.weight_scale_inv" => (W2Scale, local * EXPERT_W2_SCALE_STRIDE),
155	        other => anyhow::bail!("GLM5.2 expert tensor {name} has unknown projection {other}"),
156	    };
157	    Ok(Some(Glm52ExpertPlacement {
158	        layer,
159	        region,
160	        offset,
161	    }))
162	}
