190	impl Glm52RankLoadBundle {
191	    fn planned_total_bytes(&self) -> Result<usize> {
192	        self.shards
193	            .iter()
194	            .flat_map(|shard| shard.tensors.iter())
195	            .try_fold(0usize, |total, spec| {
196	                total
197	                    .checked_add(expected_tensor_contract(&spec.name)?.byte_len()?)
198	                    .ok_or_else(|| {
199	                        anyhow::anyhow!(
200	                            "GLM5.2 rank {} planned byte count overflow",
201	                            self.plan.rank
202	                        )
203	                    })
204	            })
205	    }
206	}
