218	impl Glm52TensorContract {
219	    fn byte_len(&self) -> Result<usize> {
220	        let elements = self.shape.iter().try_fold(1usize, |total, dim| {
221	            total.checked_mul(*dim).ok_or_else(|| {
222	                anyhow::anyhow!(
223	                    "GLM5.2 tensor shape {:?} element count overflow",
224	                    self.shape
225	                )
226	            })
227	        })?;
228	        elements
229	            .checked_mul(dtype_element_bytes(self.dtype)?)
230	            .ok_or_else(|| anyhow::anyhow!("GLM5.2 tensor {:?} byte count overflow", self.shape))
231	    }
232	}
