261	    pub(crate) fn all_rank_load_bundles(
262	        &self,
263	        moe_topo: crate::Glm52MoeTopo,
264	        native_mtp: bool,
265	    ) -> Result<Vec<Glm52RankLoadBundle>> {
266	        (0..moe_topo.device_count())
267	            .map(|rank| self.rank_load_bundle(rank, moe_topo, native_mtp))
268	            .collect()
269	    }
