324	    /// Full checkpoint coverage, including the MTP accuracy-oracle layer.
325	    /// This is a manifest invariant only: resident load plans below
326	    /// deliberately omit tensors that the serving model never consumes.
327	    fn rank_tensor_names(&self, rank: usize) -> Result<Vec<String>> {
328	        ensure!(
329	            rank < GLM52_EP_RANKS,
330	            "GLM5.2 rank must be in 0..{GLM52_EP_RANKS}, got {rank}"
331	        );
332	        let mut names = Vec::new();
333	        self.push_checkpoint_non_expert_names(&mut names);
334	        let expert_start = rank * GLM52_LOCAL_EXPERTS;
335	        let expert_range = expert_start..expert_start + GLM52_LOCAL_EXPERTS;
336	        for layer_idx in GLM52_DENSE_LAYERS..=GLM52_MTP_LAYER {
337	            push_routed_experts(&mut names, layer_idx, expert_range.clone());
338	        }
339	        Ok(names)
340	    }
341	
342	    /// Tensors that must become GPU-resident for one serving rank. MTP layer
343	    /// 78 enters the EP plan only when native MTP is enabled. TP4 gets all
344	    /// routed + shared experts from `load_tp_slice_layer`, so its first pass
345	    /// loads routers but not duplicate full shared-expert projections.
346	    fn rank_resident_tensor_names(
347	        &self,
348	        rank: usize,
349	        moe_topo: crate::Glm52MoeTopo,
350	        native_mtp: bool,
351	    ) -> Result<Vec<String>> {
352	        ensure!(
353	            rank < moe_topo.device_count(),
354	            "GLM5.2 rank must be in 0..{}, got {rank}",
355	            moe_topo.device_count()
356	        );
357	        let mut names = Vec::new();
358	        self.push_resident_non_expert_names(&mut names, moe_topo.uses_ep_expert_bundles());
359	        if moe_topo.uses_ep_expert_bundles() {
360	            let local = moe_topo.ep_local_experts();
361	            let expert_range = rank * local..(rank + 1) * local;
362	            for layer_idx in GLM52_DENSE_LAYERS..GLM52_LAYERS {
363	                push_routed_experts(&mut names, layer_idx, expert_range.clone());
364	            }
365	            if native_mtp {
366	                self.push_mtp_non_expert_names(&mut names, true);
367	                push_routed_experts(&mut names, GLM52_MTP_LAYER, expert_range);
368	            }
369	        } else {
370	            if native_mtp {
371	                self.push_mtp_non_expert_names(&mut names, false);
372	            }
373	        }
374	        Ok(names)
375	    }
376	
377	    fn push_resident_non_expert_names(
378	        &self,
379	        names: &mut Vec<String>,
380	        include_shared_experts: bool,
381	    ) {
382	        names.push("model.embed_tokens.weight".to_owned());
383	        names.push("model.norm.weight".to_owned());
384	        names.push("lm_head.weight".to_owned());
385	
386	        for layer_idx in 0..GLM52_LAYERS {
387	            self.push_attention_names(names, layer_idx);
388	            if layer_idx < GLM52_DENSE_LAYERS {
389	                push_dense_mlp(names, layer_idx);
390	            } else {
391	                push_moe_non_expert(names, layer_idx, include_shared_experts);
392	            }
393	        }
394	    }
395	
396	    fn push_checkpoint_non_expert_names(&self, names: &mut Vec<String>) {
397	        self.push_resident_non_expert_names(names, true);
398	        self.push_mtp_non_expert_names(names, true);
399	    }
