412	    fn push_attention_names(&self, names: &mut Vec<String>, layer_idx: usize) {
413	        let prefix = format!("model.layers.{layer_idx}");
414	        names.push(format!("{prefix}.input_layernorm.weight"));
415	        push_fp8(names, &format!("{prefix}.self_attn.q_a_proj"));
416	        names.push(format!("{prefix}.self_attn.q_a_layernorm.weight"));
417	        push_fp8(names, &format!("{prefix}.self_attn.q_b_proj"));
418	        push_fp8(names, &format!("{prefix}.self_attn.kv_a_proj_with_mqa"));
419	        names.push(format!("{prefix}.self_attn.kv_a_layernorm.weight"));
420	        push_fp8(names, &format!("{prefix}.self_attn.kv_b_proj"));
421	        push_fp8(names, &format!("{prefix}.self_attn.o_proj"));
422	        names.push(format!("{prefix}.post_attention_layernorm.weight"));
423	
424	        let indexer = format!("{prefix}.self_attn.indexer");
425	        if self
426	            .weight_map
427	            .contains_key(&format!("{indexer}.k_norm.weight"))
428	        {
429	            names.push(format!("{indexer}.k_norm.weight"));
430	            names.push(format!("{indexer}.k_norm.bias"));
431	            names.push(format!("{indexer}.weights_proj.weight"));
432	            push_fp8(names, &format!("{indexer}.wk"));
433	            push_fp8(names, &format!("{indexer}.wq_b"));
434	        }
435	    }
436	
437	    fn validate_rank_coverage(&self) -> Result<()> {
438	        let mut generated = BTreeSet::new();
439	        for rank in 0..GLM52_EP_RANKS {
440	            for name in self.rank_tensor_names(rank)? {
441	                generated.insert(name);
442	            }
443	        }
444	        let checkpoint = self.weight_map.keys().cloned().collect::<BTreeSet<_>>();
445	        let missing = checkpoint
446	            .difference(&generated)
447	            .take(5)
448	            .cloned()
449	            .collect::<Vec<_>>();
450	        let extra = generated
451	            .difference(&checkpoint)
452	            .take(5)
453	            .cloned()
454	            .collect::<Vec<_>>();
455	        ensure!(
456	            missing.is_empty() && extra.is_empty(),
457	            "GLM5.2 rank load plan does not exactly cover checkpoint tensors: missing_sample={missing:?}, extra_sample={extra:?}, checkpoint={}, generated={}",
458	            checkpoint.len(),
459	            generated.len()
460	        );
461	        Ok(())
462	    }
463	}
