472	fn push_moe_non_expert(names: &mut Vec<String>, layer_idx: usize, include_shared_experts: bool) {
473	    let prefix = format!("model.layers.{layer_idx}.mlp");
474	    names.push(format!("{prefix}.gate.weight"));
475	    names.push(format!("{prefix}.gate.e_score_correction_bias"));
476	    if include_shared_experts {
477	        push_fp8(names, &format!("{prefix}.shared_experts.gate_proj"));
478	        push_fp8(names, &format!("{prefix}.shared_experts.up_proj"));
479	        push_fp8(names, &format!("{prefix}.shared_experts.down_proj"));
480	    }
481	}
482	
483	fn push_routed_experts(names: &mut Vec<String>, layer_idx: usize, experts: std::ops::Range<usize>) {
484	    let prefix = format!("model.layers.{layer_idx}.mlp.experts");
485	    for expert_idx in experts {
486	        let expert = format!("{prefix}.{expert_idx}");
487	        push_fp8(names, &format!("{expert}.gate_proj"));
488	        push_fp8(names, &format!("{expert}.up_proj"));
489	        push_fp8(names, &format!("{expert}.down_proj"));
490	    }
491	}
492	
493	fn push_fp8(names: &mut Vec<String>, prefix: &str) {
494	    names.push(format!("{prefix}.weight"));
495	    names.push(format!("{prefix}.weight_scale_inv"));
496	}
497	
498	pub(crate) fn expected_tensor_contract(name: &str) -> Result<Glm52TensorContract> {
499	    if name == "model.embed_tokens.weight" || name == "lm_head.weight" {
500	        return Ok(contract(Dtype::BF16, [GLM52_VOCAB, GLM52_HIDDEN]));
501	    }
502	    if name == "model.norm.weight" {
503	        return Ok(contract(Dtype::BF16, [GLM52_HIDDEN]));
504	    }
505	
506	    let layer_idx = parse_layer_index(name)?;
507	    ensure!(
508	        layer_idx <= GLM52_MTP_LAYER,
509	        "GLM5.2 tensor contract excludes layer {layer_idx}: {name}"
510	    );
511	
512	    if layer_idx == GLM52_MTP_LAYER {
513	        if name.ends_with(".enorm.weight")
514	            || name.ends_with(".hnorm.weight")
515	            || name.ends_with(".shared_head.norm.weight")
516	        {
517	            return Ok(contract(Dtype::BF16, [GLM52_HIDDEN]));
518	        }
519	        if name.ends_with(".eh_proj.weight") {
520	            return Ok(contract(Dtype::BF16, [GLM52_HIDDEN, 2 * GLM52_HIDDEN]));
521	        }
522	    }
523	
524	    if name.ends_with(".input_layernorm.weight")
525	        || name.ends_with(".post_attention_layernorm.weight")
526	    {
527	        return Ok(contract(Dtype::BF16, [GLM52_HIDDEN]));
528	    }
529	    if name.ends_with(".self_attn.q_a_layernorm.weight") {
530	        return Ok(contract(Dtype::BF16, [GLM52_Q_LORA_RANK]));
531	    }
532	    if name.ends_with(".self_attn.kv_a_layernorm.weight") {
533	        return Ok(contract(Dtype::BF16, [GLM52_KV_LORA_RANK]));
534	    }
535	
536	    if let Some(projection) = attention_projection_contract(name) {
537	        return Ok(projection);
538	    }
539	    if let Some(indexer) = indexer_contract(name) {
540	        return Ok(indexer);
541	    }
542	    if let Some(mlp) = mlp_contract(layer_idx, name) {
543	        return Ok(mlp);
544	    }
545	
546	    anyhow::bail!("no GLM5.2 tensor contract for {name}")
547	}
548	
549	fn attention_projection_contract(name: &str) -> Option<Glm52TensorContract> {
550	    projection_contract(name, ".self_attn.q_a_proj", GLM52_Q_LORA_RANK, GLM52_HIDDEN)
551	        .or_else(|| {
552	            projection_contract(
553	                name,
554	                ".self_attn.q_b_proj",
555	                GLM52_Q_B_OUT,
556	                GLM52_Q_LORA_RANK,
557	            )
558	        })
559	        .or_else(|| {
560	            projection_contract(
561	                name,
562	                ".self_attn.kv_a_proj_with_mqa",
563	                GLM52_KV_A_OUT,
564	                GLM52_HIDDEN,
565	            )
566	        })
567	        .or_else(|| {
568	            projection_contract(
569	                name,
570	                ".self_attn.kv_b_proj",
571	                GLM52_KV_B_OUT,
572	                GLM52_KV_LORA_RANK,
573	            )
574	        })
575	        .or_else(|| projection_contract(name, ".self_attn.o_proj", GLM52_HIDDEN, GLM52_O_PROJ_IN))
576	}
577	
578	fn indexer_contract(name: &str) -> Option<Glm52TensorContract> {
579	    if name.ends_with(".self_attn.indexer.k_norm.weight")
580	        || name.ends_with(".self_attn.indexer.k_norm.bias")
581	    {
582	        return Some(contract(Dtype::BF16, [GLM52_INDEX_HEAD_DIM]));
583	    }
584	    if name.ends_with(".self_attn.indexer.weights_proj.weight") {
585	        return Some(contract(Dtype::BF16, [GLM52_INDEX_HEADS, GLM52_HIDDEN]));
586	    }
587	    projection_contract(
588	        name,
589	        ".self_attn.indexer.wk",
590	        GLM52_INDEX_HEAD_DIM,
591	        GLM52_HIDDEN,
592	    )
593	    .or_else(|| {
594	        projection_contract(
595	            name,
596	            ".self_attn.indexer.wq_b",
597	            GLM52_INDEX_HEADS * GLM52_INDEX_HEAD_DIM,
598	            GLM52_Q_LORA_RANK,
599	        )
600	    })
601	}
602	
603	fn mlp_contract(layer_idx: usize, name: &str) -> Option<Glm52TensorContract> {
604	    if name.ends_with(".mlp.gate.weight") {
605	        return Some(contract(Dtype::BF16, [GLM52_ROUTED_EXPERTS, GLM52_HIDDEN]));
606	    }
607	    if name.ends_with(".mlp.gate.e_score_correction_bias") {
608	        return Some(contract(Dtype::F32, [GLM52_ROUTED_EXPERTS]));
609	    }
610	
611	    let intermediate = if layer_idx < GLM52_DENSE_LAYERS {
612	        GLM52_DENSE_INTERMEDIATE
613	    } else {
614	        GLM52_EXPERT_INTERMEDIATE
615	    };
616	    projection_contract(name, ".gate_proj", intermediate, GLM52_HIDDEN)
617	        .or_else(|| projection_contract(name, ".up_proj", intermediate, GLM52_HIDDEN))
618	        .or_else(|| projection_contract(name, ".down_proj", GLM52_HIDDEN, intermediate))
619	}
620	
621	fn projection_contract(
622	    name: &str,
623	    stem: &str,
624	    rows: usize,
625	    cols: usize,
626	) -> Option<Glm52TensorContract> {
627	    if name.ends_with(&format!("{stem}.weight")) {
628	        return Some(contract(Dtype::F8_E4M3, [rows, cols]));
629	    }
630	    if name.ends_with(&format!("{stem}.weight_scale_inv")) {
631	        return Some(contract(
632	            Dtype::F32,
633	            [rows.div_ceil(FP8_BLOCK_SIZE), cols.div_ceil(FP8_BLOCK_SIZE)],
634	        ));
635	    }
636	    None
637	}
638	
639	fn contract<const N: usize>(dtype: Dtype, shape: [usize; N]) -> Glm52TensorContract {
640	    Glm52TensorContract {
641	        dtype,
642	        shape: shape.to_vec(),
643	    }
644	}
