646	fn dtype_element_bytes(dtype: Dtype) -> Result<usize> {
647	    match dtype {
648	        Dtype::F8_E4M3 => Ok(1),
649	        Dtype::BF16 => Ok(2),
650	        Dtype::F32 => Ok(4),
651	        other => anyhow::bail!("GLM5.2 loader does not support dtype {:?}", other),
652	    }
653	}
