234	impl Glm52WeightManifest {
235	    pub(crate) fn from_model_dir(model_path: &Path) -> Result<Self> {
236	        let index_path = model_path.join(GLM52_WEIGHT_INDEX);
237	        let content = std::fs::read_to_string(&index_path)
238	            .with_context(|| format!("read {}", index_path.display()))?;
239	        let json: Value = serde_json::from_str(&content)
240	            .with_context(|| format!("parse {}", index_path.display()))?;
241	        Self::from_index_json(&json)
242	    }
243	
244	    fn from_index_json(json: &Value) -> Result<Self> {
245	        let weight_map = json
246	            .get("weight_map")
247	            .and_then(Value::as_object)
248	            .ok_or_else(|| anyhow::anyhow!("GLM5.2 safetensors index missing weight_map"))?;
249	        let mut out = BTreeMap::new();
250	        for (name, shard) in weight_map {
251	            let shard = shard
252	                .as_str()
253	                .ok_or_else(|| anyhow::anyhow!("weight_map entry {name} is not a shard string"))?;
254	            out.insert(name.clone(), shard.to_owned());
255	        }
256	        let manifest = Self { weight_map: out };
257	        manifest.validate_rank_coverage()?;
258	        Ok(manifest)
259	    }
