271	    /// Shard file holding `name` (TP slice second-pass loads resolve every
272	    /// expert's tensors, not just this rank's 32-expert bundle).
273	    pub(crate) fn shard_for(&self, name: &str) -> Result<&str> {
274	        self.weight_map
275	            .get(name)
276	            .map(String::as_str)
277	            .with_context(|| format!("GLM5.2 safetensors index missing tensor {name}"))
278	    }
279	
280	    fn rank_load_bundle(
281	        &self,
282	        rank: usize,
283	        moe_topo: crate::Glm52MoeTopo,
284	        native_mtp: bool,
285	    ) -> Result<Glm52RankLoadBundle> {
286	        let names = self.rank_resident_tensor_names(rank, moe_topo, native_mtp)?;
287	        let mut by_shard: BTreeMap<String, Vec<Glm52TensorLoadSpec>> = BTreeMap::new();
288	        for name in names {
289	            let shard = self
290	                .weight_map
291	                .get(&name)
292	                .with_context(|| format!("GLM5.2 safetensors index missing tensor {name}"))?;
293	            by_shard
294	                .entry(shard.clone())
295	                .or_default()
296	                .push(Glm52TensorLoadSpec {
297	                    name,
298	                    shard: shard.clone(),
299	                });
300	        }
301	        let tensor_count = by_shard.values().map(Vec::len).sum();
302	        // Tensor-replicated topologies carry no expert tensors in the
303	        // resident plan; their bundles get an empty range.
304	        let expert_range = if moe_topo.uses_ep_expert_bundles() {
305	            let local = moe_topo.ep_local_experts();
306	            rank * local..(rank + 1) * local
307	        } else {
308	            0..0
309	        };
310	        Ok(Glm52RankLoadBundle {
311	            plan: Glm52RankWeightPlan {
312	                rank,
313	                expert_range,
314	                tensor_count,
315	                native_mtp,
316	            },
317	            shards: by_shard
318	                .into_iter()
319	                .map(|(shard, tensors)| Glm52ShardLoadPlan { shard, tensors })
320	                .collect(),
321	        })
322	    }
