437	    fn validate_rank_coverage(&self) -> Result<()> {
438	        let mut generated = BTreeSet::new();
439	        for rank in 0..GLM52_EP_RANKS {
440	            for name in self.rank_tensor_names(rank)? {
441	                generated.insert(name);
442	            }
443	        }
444	        let checkpoint = self.weight_map.keys().cloned().collect::<BTreeSet<_>>();
445	        let missing = checkpoint
446	            .difference(&generated)
447	            .take(5)
448	            .cloned()
449	            .collect::<Vec<_>>();
450	        let extra = generated
451	            .difference(&checkpoint)
452	            .take(5)
453	            .cloned()
454	            .collect::<Vec<_>>();
455	        ensure!(
456	            missing.is_empty() && extra.is_empty(),
457	            "GLM5.2 rank load plan does not exactly cover checkpoint tensors: missing_sample={missing:?}, extra_sample={extra:?}, checkpoint={}, generated={}",
458	            checkpoint.len(),
459	            generated.len()
460	        );
461	        Ok(())
462	    }
463	}
