498	pub(crate) fn expected_tensor_contract(name: &str) -> Result<Glm52TensorContract> {
499	    if name == "model.embed_tokens.weight" || name == "lm_head.weight" {
500	        return Ok(contract(Dtype::BF16, [GLM52_VOCAB, GLM52_HIDDEN]));
501	    }
502	    if name == "model.norm.weight" {
503	        return Ok(contract(Dtype::BF16, [GLM52_HIDDEN]));
504	    }
505	
506	    let layer_idx = parse_layer_index(name)?;
507	    ensure!(
508	        layer_idx <= GLM52_MTP_LAYER,
509	        "GLM5.2 tensor contract excludes layer {layer_idx}: {name}"
510	    );
511	
512	    if layer_idx == GLM52_MTP_LAYER {
513	        if name.ends_with(".enorm.weight")
514	            || name.ends_with(".hnorm.weight")
515	            || name.ends_with(".shared_head.norm.weight")
516	        {
517	            return Ok(contract(Dtype::BF16, [GLM52_HIDDEN]));
518	        }
519	        if name.ends_with(".eh_proj.weight") {
520	            return Ok(contract(Dtype::BF16, [GLM52_HIDDEN, 2 * GLM52_HIDDEN]));
521	        }
522	    }
523	
524	    if name.ends_with(".input_layernorm.weight")
525	        || name.ends_with(".post_attention_layernorm.weight")
526	    {
527	        return Ok(contract(Dtype::BF16, [GLM52_HIDDEN]));
528	    }
529	    if name.ends_with(".self_attn.q_a_layernorm.weight") {
530	        return Ok(contract(Dtype::BF16, [GLM52_Q_LORA_RANK]));
531	    }
532	    if name.ends_with(".self_attn.kv_a_layernorm.weight") {
533	        return Ok(contract(Dtype::BF16, [GLM52_KV_LORA_RANK]));
534	    }
535	
536	    if let Some(projection) = attention_projection_contract(name) {
537	        return Ok(projection);
538	    }
539	    if let Some(indexer) = indexer_contract(name) {
540	        return Ok(indexer);
541	    }
542	    if let Some(mlp) = mlp_contract(layer_idx, name) {
543	        return Ok(mlp);
544	    }
545	
546	    anyhow::bail!("no GLM5.2 tensor contract for {name}")
547	}
