603	fn mlp_contract(layer_idx: usize, name: &str) -> Option<Glm52TensorContract> {
604	    if name.ends_with(".mlp.gate.weight") {
605	        return Some(contract(Dtype::BF16, [GLM52_ROUTED_EXPERTS, GLM52_HIDDEN]));
606	    }
607	    if name.ends_with(".mlp.gate.e_score_correction_bias") {
608	        return Some(contract(Dtype::F32, [GLM52_ROUTED_EXPERTS]));
609	    }
610	
611	    let intermediate = if layer_idx < GLM52_DENSE_LAYERS {
612	        GLM52_DENSE_INTERMEDIATE
613	    } else {
614	        GLM52_EXPERT_INTERMEDIATE
615	    };
616	    projection_contract(name, ".gate_proj", intermediate, GLM52_HIDDEN)
617	        .or_else(|| projection_contract(name, ".up_proj", intermediate, GLM52_HIDDEN))
618	        .or_else(|| projection_contract(name, ".down_proj", GLM52_HIDDEN, intermediate))
619	}
