621	fn projection_contract(
622	    name: &str,
623	    stem: &str,
624	    rows: usize,
625	    cols: usize,
626	) -> Option<Glm52TensorContract> {
627	    if name.ends_with(&format!("{stem}.weight")) {
628	        return Some(contract(Dtype::F8_E4M3, [rows, cols]));
629	    }
630	    if name.ends_with(&format!("{stem}.weight_scale_inv")) {
631	        return Some(contract(
632	            Dtype::F32,
633	            [rows.div_ceil(FP8_BLOCK_SIZE), cols.div_ceil(FP8_BLOCK_SIZE)],
634	        ));
635	    }
636	    None
637	}
