655	fn parse_layer_index(name: &str) -> Result<usize> {
656	    let rest = name
657	        .strip_prefix("model.layers.")
658	        .ok_or_else(|| anyhow::anyhow!("GLM5.2 tensor is not a layer tensor: {name}"))?;
659	    let (idx, _) = rest
660	        .split_once('.')
661	        .ok_or_else(|| anyhow::anyhow!("GLM5.2 tensor has malformed layer prefix: {name}"))?;
662	    idx.parse::<usize>()
663	        .map_err(|err| anyhow::anyhow!("GLM5.2 tensor has invalid layer index in {name}: {err}"))
664	}
