666	/// Reinterpret an owned device byte buffer as a typed slice (no copy). The
667	/// loader keeps every region as raw `u8`; consumers retype at construction.
668	pub(crate) fn retype_owned<T>(
669	    stream: &std::sync::Arc<cudarc::driver::CudaStream>,
670	    bytes: cudarc::driver::CudaSlice<u8>,
671	) -> Result<cudarc::driver::CudaSlice<T>> {
672	    ensure!(
673	        bytes.len().is_multiple_of(std::mem::size_of::<T>()),
674	        "GLM5.2 retype: {} bytes is not a multiple of element size {}",
675	        bytes.len(),
676	        std::mem::size_of::<T>()
677	    );
678	    let len = bytes.len() / std::mem::size_of::<T>();
679	    let ptr = bytes.leak();
680	    // SAFETY: ptr is a live device allocation of exactly len*size_of::<T>()
681	    // bytes (leaked just above); cudaMalloc alignment (256B) covers any T we
682	    // use (f32/bf16/i32).
683	    Ok(unsafe { stream.upgrade_device_ptr::<T>(ptr, len) })
684	}
