686	pub(crate) fn mmap_file(path: &Path) -> Result<Mmap> {
687	    let file = std::fs::File::open(path)
688	        .map_err(|err| anyhow::anyhow!("open {}: {err}", path.display()))?;
689	    unsafe { Mmap::map(&file) }.map_err(|err| anyhow::anyhow!("mmap {}: {err}", path.display()))
690	}
