238	        .and_then(Value::as_array)
239	        .ok_or_else(|| anyhow::anyhow!("GLM5.2 quantization_config.weight_block_size missing"))?;
240	    ensure!(
241	        block.len() == 2 && block[0].as_u64() == Some(128) && block[1].as_u64() == Some(128),
242	        "GLM5.2 weight_block_size must be [128, 128]"
243	    );
244	    Ok(())
