246	
247	fn string_field(json: &Value, key: &str) -> Result<String> {
248	    json.get(key)
249	        .and_then(Value::as_str)
250	        .map(ToOwned::to_owned)
251	        .ok_or_else(|| anyhow::anyhow!("missing string field {key}"))
252	}
253	
254	fn string_array_field(json: &Value, key: &str) -> Result<Vec<String>> {
255	    let values = json
256	        .get(key)
257	        .and_then(Value::as_array)
258	        .ok_or_else(|| anyhow::anyhow!("missing string array field {key}"))?;
259	    values
260	        .iter()
261	        .map(|value| {
262	            value
263	                .as_str()
264	                .map(ToOwned::to_owned)
265	                .ok_or_else(|| anyhow::anyhow!("field {key} contains a non-string entry"))
266	        })
267	        .collect()
268	}
269	
270	fn usize_field(json: &Value, key: &str) -> Result<usize> {
271	    let value = json
272	        .get(key)
273	        .and_then(Value::as_u64)
274	        .ok_or_else(|| anyhow::anyhow!("missing unsigned integer field {key}"))?;
275	    usize::try_from(value).with_context(|| format!("field {key} does not fit usize"))
276	}
277	
278	fn bool_field(json: &Value, key: &str) -> Result<bool> {
279	    json.get(key)
280	        .and_then(Value::as_bool)
281	        .ok_or_else(|| anyhow::anyhow!("missing bool field {key}"))
282	}
283	
284	fn number_field(json: &Value, key: &str) -> Result<f64> {
285	    json.get(key)
286	        .and_then(Value::as_f64)
287	        .ok_or_else(|| anyhow::anyhow!("missing numeric field {key}"))
288	}
289	
290	fn ensure_eq_usize(json: &Value, key: &str, expected: usize) -> Result<()> {
291	    let actual = usize_field(json, key)?;
292	    ensure!(
293	        actual == expected,
294	        "{key} mismatch: got {actual}, expected {expected}"
295	    );
296	    Ok(())
297	}
298	
299	fn ensure_float_close(actual: f64, expected: f64, tolerance: f64, label: &str) -> Result<()> {
300	    ensure!(
301	        (actual - expected).abs() <= tolerance,
302	        "{label} mismatch: got {actual}, expected {expected}"
303	    );
304	    Ok(())
305	}
